export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = Math.max(0, u * t - g * t * t / 2);
  const v = u - g * t;
  const H = u * u / (2 * g);
  const F = m * g;
  let st = 'Ready to toss';
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 1e-6) st = 'At the top';
  else st = t < ta ? 'Rising' : 'Falling';
  const o = [];
  o.push(...sdk.panel({ x: 10, y: 40, w: 310, h: 370, title: 'The motion', state: st, id: 'lane.motion' }));
  o.push(...sdk.panel({ x: 330, y: 40, w: 300, h: 370, title: 'Velocity over time', state: '', id: 'lane.graph' }));
  const y0 = 385, ppm = 150;
  o.push(sdk.axis('axis.h', { x: 80, y: y0, length: 2.2 * ppm, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const by = y0 - y * ppm;
  o.push(sdk.circle('ball.toss', 160, by, 26));
  o.push(...sdk.vector('vec.v', { x: 190, y: by }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 130, y: by }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(215, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const f = (x) => u - g * x;
  const pts = [], past = [];
  for (let i = 0; i <= 12; i++) { const x = 1.8 * i / 12; pts.push({ x, y: sdk.clamp(f(x), -5.5, 5.5) }); }
  const n = 10;
  for (let i = 0; i <= n; i++) { const x = t * i / n; past.push({ x, y: sdk.clamp(f(x), -5.5, 5.5) }); }
  const x1 = sdk.clamp(t - 0.15, 0, 1.8), x2 = sdk.clamp(t + 0.15, 0, 1.8);
  const series = [{ label: 'v = u - g t', kind: 'line', points: pts }];
  if (t > 0) series.push({ label: 'so far', kind: 'line', points: past });
  series.push({ label: 'slope a = -g', kind: 'line', points: [{ x: x1, y: sdk.clamp(f(x1), -5.5, 5.5) }, { x: x2, y: sdk.clamp(f(x2), -5.5, 5.5) }] });
  o.push(...[sdk.plot('plot.vt', { x: 350, y: 60, w: 270, h: 340, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series })]);
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F, velocity_: v } };
}
